#!/usr/bin/env python3
"""Focused logic test for CVE-2020-14331 vgacon scrollback bounds guard.

Runs with cwd = a checkout of the target with the candidate patch applied.
- patched source:   drivers/video/console/vgacon.c (working tree)
- unpatched source: git show HEAD:drivers/video/console/vgacon.c (target commit)

It extracts the real vgacon_scrollback_update() body from both revisions,
compiles each in a guarded harness (buffer + canary trailer), and asserts:
  * patched   -> no out-of-bounds byte written (guard wraps tail to 0)
  * unpatched -> out-of-bounds byte written (canary corrupted)
"""
import re
import subprocess
import sys
import tempfile
from pathlib import Path

SRC = "drivers/video/console/vgacon.c"
FUNC = "vgacon_scrollback_update"


def extract(text: str) -> str:
    lines = text.splitlines()
    out = []
    started = False
    for line in lines:
        if not started:
            if re.match(r"^static void %s\(" % re.escape(FUNC), line):
                started = True
                out.append(line)
            continue
        out.append(line)
        if line == "}":
            break
    if not started:
        raise SystemExit("FAIL: function %s not found" % FUNC)
    return "\n".join(out)


def patched_source() -> str:
    return Path(SRC).read_text(encoding="utf-8", errors="replace")


def unpatched_source() -> str:
    return subprocess.run(
        ["git", "show", "HEAD:" + SRC],
        check=True, capture_output=True, text=True,
        encoding="utf-8", errors="replace",
    ).stdout


STUBS = r"""
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

struct vc_data {
	unsigned long vc_origin;
	unsigned int  vc_size_row;
	int           vc_num;
};

static void *vgacon_scrollback;
static int vgacon_scrollback_tail;
static int vgacon_scrollback_size;
static int vgacon_scrollback_rows;
static int vgacon_scrollback_cnt;
static int vgacon_scrollback_cur;
static int fg_console = 0;

#define scr_memcpyw(dst, src, n) memcpy((dst), (src), (n))
"""

MAIN = r"""
#define BUF_SZ   100
#define CANARY   64

int main(void)
{
	unsigned char raw[BUF_SZ + CANARY];
	unsigned char src[4096];
	struct vc_data c;
	int i, corrupted = 0;

	memset(raw, 0xAA, sizeof(raw));
	memset(src, 0x55, sizeof(src));

	vgacon_scrollback      = raw;
	vgacon_scrollback_size = BUF_SZ;   /* sized with the OLD row size */
	vgacon_scrollback_rows = 9;
	vgacon_scrollback_cnt  = 0;
	vgacon_scrollback_cur  = 0;
	/* tail leaves room only for the old 10-byte row, not the new 60-byte row */
	vgacon_scrollback_tail = 50;

	c.vc_origin   = (unsigned long)src;
	c.vc_size_row = 60;                /* console resized: row grew 10 -> 60 */
	c.vc_num      = fg_console;

	vgacon_scrollback_update(&c, 0, 1);

	for (i = BUF_SZ; i < BUF_SZ + CANARY; i++) {
		if (raw[i] != 0xAA)
			corrupted = 1;
	}

	printf("tail=%d size=%d wrote_past_buffer=%d\n",
	       vgacon_scrollback_tail, vgacon_scrollback_size, corrupted);
	return corrupted ? 1 : 0;
}
"""


def build_and_run(name: str, body: str, tmp: Path) -> int:
    cfile = tmp / (name + ".c")
    exe = tmp / name
    cfile.write_text(STUBS + body + "\n" + MAIN, encoding="utf-8")
    compile_cmd = ["gcc-10", "-w", "-O0", "-o", str(exe), str(cfile)]
    r = subprocess.run(compile_cmd, capture_output=True, text=True)
    if r.returncode != 0:
        print("FAIL: compile %s: %s" % (name, r.stderr.strip()))
        sys.exit(2)
    r = subprocess.run([str(exe)], capture_output=True, text=True)
    print("%s: %s(exit=%d)" % (name, r.stdout.strip(), r.returncode))
    return r.returncode


def main() -> int:
    patched = extract(patched_source())
    unpatched = extract(unpatched_source())
    if "(vgacon_scrollback_tail + c->vc_size_row)" not in patched:
        print("FAIL: patched function does not contain the expected guard")
        return 2
    if "(vgacon_scrollback_tail + c->vc_size_row)" in unpatched:
        print("FAIL: unpatched target unexpectedly contains the guard")
        return 2
    with tempfile.TemporaryDirectory(prefix="vgacon-logic-") as td:
        tmp = Path(td)
        p = build_and_run("patched", patched, tmp)
        u = build_and_run("unpatched", unpatched, tmp)
    ok = (p == 0) and (u != 0)
    print("RESULT:", "PASS" if ok else "FAIL",
          "(patched in-bounds=%d, unpatched overflows=%d)" % (p == 0, u != 0))
    return 0 if ok else 1


if __name__ == "__main__":
    raise SystemExit(main())

